#include "MK64F12.h"

/* Kinetis splits this in two: SIM gates the clock, PORT muxes the
   pin, GPIO drives it. Miss the SIM line and the PORT writes do
   nothing at all. */
SIM->SCGC5 |= SIM_SCGC5_PORTB_MASK;

PORTB->PCR[22] = PORT_PCR_MUX(1);     /* ALT1 = plain GPIO */

GPIOB->PDDR |= (1u << 22);            /* 1 = output */
GPIOB->PCOR  = (1u << 22);            /* clear, LED on  */
GPIOB->PSOR  = (1u << 22);            /* set,   LED off */
GPIOB->PTOR  = (1u << 22);            /* toggle */
